import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  TableRow,
  TableBody,
  TableCell,
  Typography,
  TableContainer,
  TablePagination,
} from '@mui/material';
import { axios } from '../utils/axios';
import { updateUrlParams } from '../utils/urlUtilis';
// components
import Label from '../components/label';
import Scrollbar from '../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../sections/@dashboard/user';
import { useMyContext } from './provider';
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';

export default function UserPage() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)
  
  const [search, setsearch] = useState('');
  const [page, setPage] = useState(parseInt(queryParams.get('page'),10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'),10) || 10);
  const [upcomingList, setUpcomingList] = useState([]);
  const [cancellationPolicy, setCancellationPolicy] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const{i18} = useMyContext();

  const TABLE_HEAD = [
    { id: 'bookingid', label: i18?.BOOKINGSLIST?.BOOKING_ID || 'BookingId', alignRight: false },
    { id: 'bookedDate', label: i18?.BOOKINGSLIST?.CREATED || 'Created', alignRight: false },
    { id: 'propertyid', label: i18?.BOOKINGSLIST?.LISTING_ID || 'PropertyId', alignRight: false },
    { id: 'propertyName', label: i18?.BOOKINGSLIST?.PROPERTY_NAME || 'Property Name', alignRight: false },
    { id: 'category', label: i18?.BOOKINGSLIST?.CATEGORY || 'Category', alignRight: false },
    { id: 'providerid', label: i18?.BOOKINGSLIST?.PROVIDER_ID || 'ProviderId', alignRight: false },
    { id: 'providername', label: i18?.BOOKINGSLIST?.PROVIDER_NAME || 'ProviderName', alignRight: false },
    { id: 'night', label: i18?.BOOKINGSLIST?.NIGHTS || 'Nights', alignRight: false },
    { id: 'adults', label: i18?.BOOKINGSLIST?.ADULTS || 'Adults', alignRight: false },
    { id: 'children', label: i18?.BOOKINGSLIST?.CHILDREN || 'Children', alignRight: false },
    { id: 'pets', label: i18?.BOOKINGSLIST?.PETS || 'Pets', alignRight: false },
    { id: 'perday', label: i18?.BOOKINGSLIST?.AMOUNT_PER_DAY || 'Amount / day', alignRight: false },
    { id: 'perhour', label: i18?.BOOKINGSLIST?.AMOUNT_PER_HOUR || 'Amount / hour', alignRight: false },
    { id: 'host', label: i18?.BOOKINGSLIST?.HOST_AMOUNT || 'HostAmount', alignRight: false },
    { id: 'commission', label: i18?.BOOKINGSLIST?.ADMIN_COMMISSION || 'Admin Commission', alignRight: false },
    { id: 'startdate', label: i18?.BOOKINGSLIST?.CHECKIN || 'CheckIn', alignRight: false },
    { id: 'enddate', label: i18?.BOOKINGSLIST?.CHECKOUT || 'CheckOut', alignRight: false },
    { id: 'status', label: i18?.BOOKINGSLIST?.STATUS || 'Status', alignRight: false },
    { id: 'fare', label: i18?.BOOKINGSLIST?.FARE_AMOUNT || 'Rate', alignRight: false },
    { id: 'paiddate', label: i18?.BOOKINGSLIST?.PAID_DATE || 'Paid Date', alignRight: false }
  ];
  

  const fetchData = async () => {
    try {
      let url = `module/listing/booking/upcomming?_page=${page}&_limit=${rowsPerPage}`;
      if (search) {
        url += `&search=${search}`;
        setPage(1);
      }
      const res = await axios.get(url);
      if (res.status === 200) {
        setUpcomingList(res.data.data[0].data);
        setTotalCount(res.data.data[0].totalCount[0]?.total);
        setCancellationPolicy(res.data.data[1].cancellationPolicy);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err.message || err?.response?.data?.message);
    }
  };
  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = upcomingList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(1);
    setFilterName(event.target.value);
  };

  return (
    <>
      <Helmet>
        <title> Manage Trips useEff| Admin panel </title>
      </Helmet>

      <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
        <Typography variant="h4" gutterBottom>
          {i18?.BOOKINGSLIST.UPCOMING_TRIPS || "Upcoming Trips"}
        </Typography>
      </Stack>

      <Card>
        <UserListToolbar
          numSelected={selected.length}
          filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />

        <Scrollbar>
          <TableContainer sx={{ minWidth: 800 }}>
            <Table>
              <UserListHead
                order={order}
                orderBy={orderBy}
                headLabel={TABLE_HEAD}
                rowCount={upcomingList.length}
                numSelected={selected.length}
                onRequestSort={handleRequestSort}
                onSelectAllClick={handleSelectAllClick}
              />

              <TableBody>
                {upcomingList.map((row) => {
                  const { id, name } = row;
                  const selectedUser = selected.indexOf(name) !== -1;

                  return (
                    <TableRow
                      sx={{
                        '&:nth-of-type(odd)': {
                          backgroundColor: '#DDDDDD',
                        },
                        '&:last-child td, &:last-child th': {
                          border: 0,
                        },
                      }}
                      key={id}
                      tabIndex={-1}
                      role="checkbox"
                      selected={selectedUser}
                    >
                      <TableCell padding="checkbox">
                        {/* <Checkbox checked={selectedUser} onChange={(event) => handleClick(event, name)} /> */}
                      </TableCell>
                      <TableCell align="left">{row._id}</TableCell>
                      <TableCell align="left">{row.bookingdata.createdAt?.split('T')[0]}</TableCell>
                      <TableCell align="left">{row.propertyCategoryName._id}</TableCell>
                      <TableCell align="left">
                        <a
                          target="_blank"
                          rel="noreferrer"
                          style={{ cursor: 'pointer', textDecoration: 'none', color: 'black', whiteSpace: 'nowrap' }}
                        >
                          {' '}
                          {row?.propertyName}
                        </a>
                      </TableCell>
                      <TableCell align="left">{row?.propertyCategoryName?.category}</TableCell>
                      <TableCell align="left">{row.providerId}</TableCell>
                      <TableCell align="left">{row.providerFirstname}</TableCell>
                      <TableCell align="left">{row.bookingdata.bookedHours.nights}</TableCell>
                      <TableCell align="left">{row.bookingdata.adults}</TableCell>
                      <TableCell align="left">{row.bookingdata.children}</TableCell>
                      <TableCell align="left">{row.bookingdata.pets}</TableCell>
                      <TableCell align="left">{row.bookingdata.perDay}</TableCell>
                      <TableCell align="left">{row.bookingdata.perHour}</TableCell>
                      <TableCell align="left">{row.bookingdata.hostAmount}</TableCell>
                      <TableCell align="left">{row.bookingdata.commission}</TableCell>
                      <TableCell align="left">{row.bookingdata.bookedDates.start?.split('T')[0]}</TableCell>
                      <TableCell align="left">{row.bookingdata.bookedDates.end?.split('T')[0]}</TableCell>
                      <TableCell align="left">
                        <Label color="success">{row.bookingdata.status}</Label>
                      </TableCell>
                      <TableCell align="left">
                        {row.bookingdata.currency} {row.bookingdata.fareAmount}
                      </TableCell>
                      <TableCell align="left">{row.bookingdata.paidDate?.split('T')[0]}</TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>

              {upcomingList.length === 0 && (
                <TableBody>
                  <TableRow>
                    <TableCell align="center" colSpan={12} sx={{ py: 3 }}>
                      <Paper
                        sx={{
                          textAlign: 'center',
                        }}
                      >
                        <Typography variant="h6" paragraph>
                        {i18?.BOOKINGSLIST.NO_DATA_FOUND || "No Data Found"}
                        </Typography>
                      </Paper>
                    </TableCell>
                  </TableRow>
                </TableBody>
              )}
            </Table>
          </TableContainer>
        </Scrollbar>

        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={totalCount || '0'}
          rowsPerPage={rowsPerPage}
          page={page - 1}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          sx={{
            '.MuiTablePagination-selectLabel': {
              marginTop: '12px',
            },
            '.MuiTablePagination-displayedRows': {
              marginTop: '12px',
            },
            '.MuiTablePagination-actions': {
              marginBottom: '6px',
            }
          }}
        />
      </Card>
      {/* <Typography variant="h6" paragraph sx={{ my: 3, px: 3 }}>
        Notes *
      </Typography>
      <>
        {cancellationPolicy.map((item) => (
          <>
            <Typography sx={{ px: 3 }}>
              {item.id} - {item.title} : {item.desc}
            </Typography>
          </>
        ))}
      </> */}
    </>
  );
}
